/**
 * 语言回退色块（120×120 PNG，base64 内嵌）。
 *
 * 用途：/api/tile 取不到仓库所有者头像时返回它。企微在个人微信里抓第三方
 * 图床会随机失败（同一批 8 张里常有几张只剩 GitHub 灰头像），宁可显示
 * 语言色块也不要破图。
 *
 * 为什么内嵌而不是放 public/：这个项目的部署面只有 api/，静态目录不保证
 * 被服务；而函数 bundle 里的字符串一定跟着走。24 张合计约 40KB。
 *
 * 生成方式（一次性）：临时安装 @resvg/resvg-js，用 GitHub linguist 的官方
 * 语言色渲染 120×120 圆角色块，跑完卸掉依赖。
 */
export const LANGUAGE_TILES: Record<string, string> = {
  'python': '',
  'typescript': '',
  'javascript': '',
  'go': '',
  'rust': '',
  'java': '',
  'c': '',
  'c++': '',
  'c#': '',
  'php': '',
  'ruby': '',
  'swift': '',
  'kotlin': '',
  'dart': '',
  'shell': '',
  'html': '',
  'css': '',
  'vue': '',
  'lua': '',
  'jupyter notebook': '',
  'dockerfile': '',
  'makefile': '',
  'scss': '',
  'powershell': '',
  'default': '',
};

/** 未知语言/没有语言时的兜底色块（品牌深蓝 + 星）。 */
export const DEFAULT_LANGUAGE_TILE = LANGUAGE_TILES.default as string;

/** 语言名（大小写、空白不敏感）→ 色块 base64。 */
export function tileBase64(language: string | null | undefined): string {
  const key = (language ?? '').trim().toLowerCase();
  return LANGUAGE_TILES[key] ?? DEFAULT_LANGUAGE_TILE;
}
